START TRANSACTION;
INSERT INTO canons (code,name,book_count,is_default) VALUES ('protestant-66','Protestant 66-book canon',66,FALSE) ON DUPLICATE KEY UPDATE name=VALUES(name),book_count=66;
INSERT INTO canon_books (canon_id,book_id,position,chapter_count)
SELECT c.id,b.id,CASE b.code WHEN 'GEN' THEN 1 WHEN 'EXO' THEN 2 WHEN 'LEV' THEN 3 WHEN 'NUM' THEN 4 WHEN 'DEU' THEN 5 WHEN 'JOS' THEN 6 WHEN 'JDG' THEN 7 WHEN 'RUT' THEN 8 WHEN '1SA' THEN 9 WHEN '2SA' THEN 10 WHEN '1KI' THEN 11 WHEN '2KI' THEN 12 WHEN '1CH' THEN 13 WHEN '2CH' THEN 14 WHEN 'EZR' THEN 15 WHEN 'NEH' THEN 16 WHEN 'EST' THEN 17 WHEN 'JOB' THEN 18 WHEN 'PSA' THEN 19 WHEN 'PRO' THEN 20 WHEN 'ECC' THEN 21 WHEN 'SNG' THEN 22 WHEN 'ISA' THEN 23 WHEN 'JER' THEN 24 WHEN 'LAM' THEN 25 WHEN 'EZK' THEN 26 WHEN 'DAN' THEN 27 WHEN 'HOS' THEN 28 WHEN 'JOL' THEN 29 WHEN 'AMO' THEN 30 WHEN 'OBA' THEN 31 WHEN 'JON' THEN 32 WHEN 'MIC' THEN 33 WHEN 'NAM' THEN 34 WHEN 'HAB' THEN 35 WHEN 'ZEP' THEN 36 WHEN 'HAG' THEN 37 WHEN 'ZEC' THEN 38 WHEN 'MAL' THEN 39 WHEN 'MAT' THEN 40 WHEN 'MRK' THEN 41 WHEN 'LUK' THEN 42 WHEN 'JHN' THEN 43 WHEN 'ACT' THEN 44 WHEN 'ROM' THEN 45 WHEN '1CO' THEN 46 WHEN '2CO' THEN 47 WHEN 'GAL' THEN 48 WHEN 'EPH' THEN 49 WHEN 'PHP' THEN 50 WHEN 'COL' THEN 51 WHEN '1TH' THEN 52 WHEN '2TH' THEN 53 WHEN '1TI' THEN 54 WHEN '2TI' THEN 55 WHEN 'TIT' THEN 56 WHEN 'PHM' THEN 57 WHEN 'HEB' THEN 58 WHEN 'JAS' THEN 59 WHEN '1PE' THEN 60 WHEN '2PE' THEN 61 WHEN '1JN' THEN 62 WHEN '2JN' THEN 63 WHEN '3JN' THEN 64 WHEN 'JUD' THEN 65 WHEN 'REV' THEN 66 END,MAX(cb.chapter_count)
FROM canons c JOIN books b ON FIND_IN_SET(b.code,'GEN,EXO,LEV,NUM,DEU,JOS,JDG,RUT,1SA,2SA,1KI,2KI,1CH,2CH,EZR,NEH,EST,JOB,PSA,PRO,ECC,SNG,ISA,JER,LAM,EZK,DAN,HOS,JOL,AMO,OBA,JON,MIC,NAM,HAB,ZEP,HAG,ZEC,MAL,MAT,MRK,LUK,JHN,ACT,ROM,1CO,2CO,GAL,EPH,PHP,COL,1TH,2TH,1TI,2TI,TIT,PHM,HEB,JAS,1PE,2PE,1JN,2JN,3JN,JUD,REV')>0 JOIN canon_books cb ON cb.book_id=b.id
WHERE c.code='protestant-66' GROUP BY c.id,b.id,b.code
ON DUPLICATE KEY UPDATE position=VALUES(position),chapter_count=VALUES(chapter_count);
INSERT INTO translations (provider_id,canon_id,code,name,language_code,copyright_notice,license_url,offline_allowed,is_active)
SELECT p.id,c.id,'KJV','King James Version','en','Public domain. Source package: eBible.org eng-kjv.','https://ebible.org/Scriptures/details.php?id=eng-kjv',TRUE,FALSE
FROM bible_providers p JOIN canons c ON c.code='protestant-66' WHERE p.code='local'
ON DUPLICATE KEY UPDATE name=VALUES(name),copyright_notice=VALUES(copyright_notice),license_url=VALUES(license_url),offline_allowed=TRUE;
INSERT INTO schema_migrations (version) VALUES ('006_kjv_translation') ON DUPLICATE KEY UPDATE version=VALUES(version);
COMMIT;
